def carry_over_numbering(apps, schema_editor):
    """Existing documents were numbered per register: keep that as their series
    and carry the counters into DocumentSequence."""
    Sale = apps.get_model("sales", "Sale")
    CreditNote = apps.get_model("sales", "CreditNote")
    DocumentSequence = apps.get_model("sales", "DocumentSequence")
    ReceiptSequence = apps.get_model("sales", "ReceiptSequence")
    CreditNoteSequence = apps.get_model("sales", "CreditNoteSequence")
    for sale in Sale.objects.exclude(receipt_seq=None).select_related("register"):
        Sale.objects.filter(pk=sale.pk).update(series=sale.register.code if sale.register_id else "",
                                               issued_at=sale.paid_at, transaction_at=sale.paid_at,
                                               invoice_type="abbreviated", payment_method="cash")
    for cn in CreditNote.objects.select_related("register"):
        CreditNote.objects.filter(pk=cn.pk).update(series=cn.register.code)
    for model, doc_type in ((ReceiptSequence, "invoice"), (CreditNoteSequence, "credit_note")):
        for row in model.objects.all():
            DocumentSequence.objects.update_or_create(
                branch_id=row.branch_id, register_key=row.register_id, fiscal_year=row.fiscal_year,
                doc_type=doc_type, defaults={"next_number": row.next_number})


